@isTest private class ApexPagesSeverityLocalEvidenceTest {
  @isTest static void severityEnumLocalEvidence() {
    ApexPages.Message errMsg = new ApexPages.Message(ApexPages.Severity.ERROR, 'err');
    System.assertEquals(ApexPages.Severity.ERROR, errMsg.getSeverity());
    ApexPages.Message infoMsg = new ApexPages.Message(ApexPages.Severity.INFO, 'info');
    System.assertEquals(ApexPages.Severity.INFO, infoMsg.getSeverity());
    ApexPages.Message warnMsg = new ApexPages.Message(ApexPages.Severity.WARNING, 'warn');
    System.assertEquals(ApexPages.Severity.WARNING, warnMsg.getSeverity());
    ApexPages.Message confMsg = new ApexPages.Message(ApexPages.Severity.CONFIRM, 'conf');
    System.assertEquals(ApexPages.Severity.CONFIRM, confMsg.getSeverity());
    ApexPages.Message fatalMsg = new ApexPages.Message(ApexPages.Severity.FATAL, 'fatal');
    System.assertEquals(ApexPages.Severity.FATAL, fatalMsg.getSeverity());
    System.assert(ApexPages.Severity.ERROR != ApexPages.Severity.INFO);
    System.assert(ApexPages.Severity.ERROR != ApexPages.Severity.WARNING);
    System.assert(ApexPages.Severity.ERROR != ApexPages.Severity.CONFIRM);
    System.assert(ApexPages.Severity.ERROR != ApexPages.Severity.FATAL);
  }
}
